from pathlib import Path
import subprocess

roots = [
    Path("tests/zigbee_device_emulator/managed_components"),
    Path("managed_components"),
    Path("components"),
    Path.home() / "esp",
    Path.home() / ".espressif",
]
needles = (
    "zone status change",
    "zone_status_change",
    "status_change_notification",
    "ias_zone_status",
    "ZONE_STATUS_CHANGE",
)
print("=== TEXT MATCHES ===")
seen = 0
for root in roots:
    if not root.exists():
        continue
    for p in root.rglob("*"):
        if not p.is_file() or p.suffix.lower() not in {".h",".c",".cc",".cpp",".inc"}:
            continue
        try:
            text = p.read_text(errors="ignore")
        except Exception:
            continue
        low = text.lower()
        if "ias" not in low or ("zone" not in low and "status" not in low):
            continue
        lines = text.splitlines()
        for i, line in enumerate(lines, 1):
            ll = line.lower()
            if any(n.lower() in ll for n in needles):
                print(f"{p}:{i}:{line}")
                for j in range(max(1,i-4), min(len(lines),i+5)+1):
                    if j != i:
                        print(f"  {j}: {lines[j-1]}")
                seen += 1
                if seen >= 120:
                    break
        if seen >= 120:
            break
    if seen >= 120:
        break

print("=== IAS HEADERS ===")
headers = []
for root in roots:
    if not root.exists():
        continue
    for p in root.rglob("*.h"):
        n = p.name.lower()
        if "ias" in n and "zone" in n:
            headers.append(p)
for p in sorted(set(headers))[:80]:
    print(p)

print("=== EXPORTED SYMBOLS ===")
count = 0
for root in roots[:2] + [Path("tests/zigbee_device_emulator/build"), Path("build")]:
    if not root.exists():
        continue
    for p in root.rglob("*"):
        if not p.is_file() or p.suffix.lower() not in {".a",".so",".dylib"}:
            continue
        try:
            out = subprocess.run(["nm","-g",str(p)], capture_output=True, text=True, timeout=20).stdout
        except Exception:
            continue
        hits = [ln for ln in out.splitlines() if "ias" in ln.lower() and "zone" in ln.lower() and ("status" in ln.lower() or "notif" in ln.lower())]
        if hits:
            print("LIB="+str(p))
            for ln in hits[:40]:
                print(ln)
            count += len(hits)
            if count >= 120:
                break
    if count >= 120:
        break

print("=== ESP ZIGBEE PUBLIC HEADER MATCHES ===")
for root in [Path.home()/"esp", Path.home()/".espressif"]:
    if not root.exists():
        continue
    matched = 0
    for p in root.rglob("*.h"):
        try:
            text = p.read_text(errors="ignore")
        except Exception:
            continue
        low = text.lower()
        if "ias" in low and "zone" in low and "status" in low:
            for i,line in enumerate(text.splitlines(),1):
                ll=line.lower()
                if "ias" in ll and "zone" in ll and ("status" in ll or "notification" in ll):
                    print(f"{p}:{i}:{line}")
                    matched += 1
                    if matched >= 120:
                        break
        if matched >= 120:
            break

print("INVESTIGATION_COMPLETE=1")
print("REPORT_REQUIRED=exact callable API/signature if any for IAS Zone Status Change Notification; whether EZBee exposes it; whether ESP Zigbee exposes a lower-level public API; smallest standards-correct way to emit ZoneStatus 0x0001 then 0x0000 after enrollment; no file modifications.")
